WITH seed_data (id, category, question, answer, keywords, sort_order) AS (
	VALUES
		('10000000-0000-0000-0000-000000000001'::uuid, 'booking', 'Как забронировать баню?', 'Откройте карточку объекта, выберите дату и непрерывный интервал свободных слотов, проверьте стоимость в checkout, укажите контакты и подтвердите бронь.', ARRAY['бронирование', 'забронировать', 'как забронировать', 'слоты', 'checkout', 'записаться']::text[], 1),
		('10000000-0000-0000-0000-000000000002'::uuid, 'booking', 'Можно ли изменить бронирование?', 'Да. В деталях бронирования можно изменить дату, время и количество гостей. Для активной брони доступно до трёх изменений, если визит ещё не начался.', ARRAY['изменить бронирование', 'перенести', 'поменять дату', 'изменить время', 'модификация']::text[], 2),
		('10000000-0000-0000-0000-000000000003'::uuid, 'cancellation', 'Как отменить бронирование?', 'Перейдите в «Мои бронирования», откройте нужную бронь и нажмите «Отменить». Перед подтверждением сервис покажет актуальные условия возврата по политике конкретного объекта.', ARRAY['отменить', 'отмена', 'отказаться', 'возврат при отмене', 'cancel', 'отменить бронирование']::text[], 1),
		('10000000-0000-0000-0000-000000000004'::uuid, 'cancellation', 'Где посмотреть условия возврата?', 'Политика отмены показывается на странице объекта, в checkout и в деталях бронирования. Размер возврата зависит от того, сколько времени осталось до визита.', ARRAY['возврат', 'деньги обратно', 'вернуть деньги', 'срок возврата', 'refund', 'условия возврата']::text[], 2),
		('10000000-0000-0000-0000-000000000005'::uuid, 'payment', 'Какие способы оплаты поддерживаются?', 'В клиентском checkout доступны банковская карта, СБП, Apple Pay, Google Pay и оплата из кошелька. Если на кошельке не хватает суммы, можно оплатить комбинированно: часть с кошелька, часть картой.', ARRAY['оплата', 'способ оплаты', 'карта', 'apple pay', 'google pay', 'сбп', 'payment', 'кошелёк']::text[], 1),
		('10000000-0000-0000-0000-000000000006'::uuid, 'payment', 'Что делать, если оплата не проходит?', 'Проверьте лимиты карты и повторите попытку другим способом: СБП, другая карта или кошелёк. Если платёж всё равно не подтверждается, создайте обращение в поддержку и укажите номер брони.', ARRAY['ошибка оплаты', 'не проходит оплата', 'отклонён платёж', 'проблема с оплатой', 'платёж не прошёл']::text[], 2),
		('10000000-0000-0000-0000-000000000007'::uuid, 'wallet', 'Что такое кошелёк и зачем он нужен?', 'Кошелёк BANI хранит внутренний баланс для быстрой оплаты, возвратов и бонусных начислений. Его удобно использовать, когда вы бронируете регулярно и не хотите каждый раз вводить карту.', ARRAY['кошелёк', 'баланс', 'wallet', 'зачем нужен кошелёк', 'внутренний баланс']::text[], 1),
		('10000000-0000-0000-0000-000000000008'::uuid, 'wallet', 'Как пополнить кошелёк?', 'В разделе «Кошелёк» можно пополнить баланс картой, а затем использовать эти средства для полной или частичной оплаты бронирования.', ARRAY['пополнить кошелёк', 'пополнить', 'внести деньги', 'wallet topup', 'баланс']::text[], 2),
		('10000000-0000-0000-0000-000000000009'::uuid, 'account', 'Как изменить номер телефона?', 'Откройте профиль и обновите номер телефона через подтверждение по SMS. Это нужно, чтобы бронирования, уведомления и защита аккаунта оставались привязаны к актуальному номеру.', ARRAY['изменить телефон', 'сменить номер', 'новый телефон', 'телефон', 'sms']::text[], 1),
		('10000000-0000-0000-0000-000000000010'::uuid, 'account', 'Как удалить аккаунт?', 'В профиле доступен запрос на удаление аккаунта. После подтверждения начинается 30-дневный период восстановления, в течение которого удаление можно отменить.', ARRAY['удалить аккаунт', 'удалить профиль', 'удаление', 'delete account', 'деактивация']::text[], 2),
		('10000000-0000-0000-0000-000000000011'::uuid, 'general', 'Как связаться с поддержкой?', 'Если быстрый FAQ не помог, откройте раздел «Поддержка» в кабинете клиента и создайте обращение. Для срочных вопросов используйте контакты, указанные в разделе помощи.', ARRAY['поддержка', 'связаться', 'помощь', 'support', 'контакт', 'обращение']::text[], 1),
		('10000000-0000-0000-0000-000000000012'::uuid, 'general', 'Как оставить отзыв?', 'После завершённого визита в деталях бронирования появляется действие «Оставить отзыв». Отзыв связан с реальной бронью, поэтому в профиле и карточке объекта показывается подтверждённый опыт.', ARRAY['отзыв', 'оценка', 'review', 'оставить отзыв', 'написать отзыв', 'после визита']::text[], 2)
)
INSERT INTO faq (id, category, question, answer, keywords, sort_order, active, created_at, updated_at)
SELECT seed.id, seed.category, seed.question, seed.answer, seed.keywords, seed.sort_order, true, NOW(), NOW()
FROM seed_data seed
WHERE NOT EXISTS (
	SELECT 1
	FROM faq existing
	WHERE existing.question = seed.question
);
